-- Generated by `drizzle-kit generate`, then HAND-EDITED in two places. Both
-- are deliberate; do not "tidy" them back to drizzle's output. Neither is
-- visible to `drizzle-kit`, so meta/0016_snapshot.json matches
-- lib/db/schema.ts exactly and a future `generate` produces no spurious diff.
--
--   1. `IF NOT EXISTS` on the CREATE statements. Migrations here are applied
--      BY HAND (`npm run db:migrate`) and nothing in CI applies them (the
--      2026-09-03 incident behind scripts/check-schema-drift.ts). Re-running a
--      file whose journal entry did not land must be a no-op, not an error.
--   2. The backfill INSERT..SELECT at the bottom. It is idempotent
--      (ON CONFLICT DO NOTHING on the unique index), so a re-run adds nothing.
--
-- ROLLBACK: `DROP TABLE IF EXISTS "email_suppressions";` is lossless for the
-- app ONLY after the code that reads it is reverted first (otherwise it hits
-- 42P01). Also delete this migration's row from `drizzle.__drizzle_migrations`,
-- or a later re-apply is skipped as already done. Ship order: migration first,
-- then code. The backfill is derivable from `subscriptions WHERE status =
-- 'unsubscribed'`, so dropping loses only rows written after this migration.
--
-- POST-DEPLOY STEP: after the code deploys, re-run the backfill INSERT below
-- by hand. It is idempotent, and it catches unsubscribes made between the
-- migration and the deploy (before the code wrote suppressions itself).
--
-- `source_token_hash` (nullable): on a global "stop all" row, the sha256 of the
-- unsubscribe token that wrote it, the key for the "Undo" action. The backfill
-- below leaves it NULL, so no token can lift a backfilled row.
--
-- RETIRED 'all' TARGET: its unsubscribed rows backfill as the inert pair
-- ('all', ''), NOT a global opt-out. They were system-closed with a closing
-- email in 2026-09, not a user-requested "stop all".
CREATE TABLE IF NOT EXISTS "email_suppressions" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"email" text NOT NULL,
	"target_type" text DEFAULT '' NOT NULL,
	"target_id" text DEFAULT '' NOT NULL,
	"source" text NOT NULL,
	"source_token_hash" text
);
--> statement-breakpoint
CREATE UNIQUE INDEX IF NOT EXISTS "email_suppressions_email_target_idx" ON "email_suppressions" USING btree ("email","target_type","target_id");--> statement-breakpoint
-- Backfill: every address that already opted out becomes a durable suppression
-- for that exact target. `target_id` is NULL only on the retired 'all' target.
-- `target_type <> ''` because an empty target_type would otherwise backfill as
-- a GLOBAL opt-out (the global key is the empty pair).
-- `lower(btrim(email))` cannot miss: the write path (lib/subscribe.ts) only
-- stores addresses that passed z.string().email(), which rejects ALL leading
-- and trailing whitespace (checked: space, NBSP, newline, U+3000), then applies
-- trim().toLowerCase(). So stored emails are already normalized and btrim vs
-- JS trim() cannot diverge on real data.
INSERT INTO "email_suppressions" ("email", "target_type", "target_id", "source")
SELECT DISTINCT lower(btrim("email")), "target_type", COALESCE("target_id", ''), 'backfill'
FROM "subscriptions"
WHERE "status" = 'unsubscribed' AND "target_type" <> ''
ON CONFLICT ("email", "target_type", "target_id") DO NOTHING;
